  fiber_g = EXCLUDED.fiber_g,
  source = EXCLUDED.source,
  is_verified = true,
  source_ref = EXCLUDED.source_ref
WHERE existing.is_verified IS FALSE
   OR existing.source = EXCLUDED.source
   OR existing.source LIKE 'TACO%';

